import java.util.*;

class Solution {
  public int shortestDistance(int[][] maze, int[] start, int[] destination) {
    int m = maze.length, n = maze[0].length;
    int[][] dist = new int[m][n];
    for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);
    dist[start[0]][start[1]] = 0;
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[2], b[2]));
    pq.add(new int[] {start[0], start[1], 0});
    int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    while (!pq.isEmpty()) {
      int[] c = pq.poll();
      if (c[2] > dist[c[0]][c[1]]) continue;
      if (c[0] == destination[0] && c[1] == destination[1]) return c[2];
      for (int[] d : dirs) {
        int x = c[0], y = c[1], steps = 0;
        while (x + d[0] >= 0 && x + d[0] < m && y + d[1] >= 0 && y + d[1] < n && maze[x + d[0]][y + d[1]] == 0) {
          x += d[0];
          y += d[1];
          steps++;
        }
        if (c[2] + steps < dist[x][y]) {
          dist[x][y] = c[2] + steps;
          pq.add(new int[] {x, y, dist[x][y]});
        }
      }
    }
    return -1;
  }
}
